static unsigned party_wizard_choice205(Combat*g,CampaignFollower200*m,const CombatMob*target,unsigned*outRank){if(campaignConfig200.priority[m->id]==PARTY_SUPPORT200||combat_field_slot(g)<0)return 0;for(unsigned i=0;i<COMBAT_FIELDS;i++)if(g->fields[i].remaining&&g->fields[i].companionOwner194==m->id+1)return 0;unsigned required=campaignConfig200.priority[m->id]==PARTY_OFFENSE200?2:3,best=0;int bestScore=0;static const unsigned skills[2]={80,77};for(unsigned i=0;i<2;i++){unsigned skill=skills[i],rank=party_skill_rank193(m,skill);if(!rank||m->sp<party_skill_base_cost201(skill,rank))continue;unsigned element=skill==80?1:4,count=party_field_targets205(g,element,target->x,target->y,skillDefs[skill].radius);if(count<required)continue;int score=(int)count*(skill==80?100+40*(int)rank:80+20*(int)rank)*class_element_rate48(target,(int)element);if(score>bestScore){best=skill;bestScore=score;*outRank=rank;}}return best;}
static int party_wizard_begin205(Combat*g,CampaignFollower200*m,const CombatMob*target,unsigned skill,unsigned rank){const CastTiming*timing=cast_timing(skill);if(!timing||!rank||rank>10||combat_dist(m->x,m->y,target->x,target->y)>skillDefs[skill].range||!party_line200(g,m->x,m->y,target->x,target->y))return 0;float dex=fminf(150,(float)party_stat200(m,4,g->time)),cast=timing->cast[rank-1]*(150-dex)/150000.f,delay=timing->delay[rank-1]/1000.f;if(cast<0)cast=0;m->groundX205=target->x;m->groundY205=target->y;m->pendingSkill=m->lastSkill=skill;m->pendingRank=rank;m->remainingHits204=1;m->attackAt=g->time;m->castUntil=m->impactAt=g->time+cast;m->attackUntil=m->castUntil+.3f;m->nextAttack=fmaxf(m->attackUntil,m->castUntil+delay);m->skillAt=m->nextAttack;if(cast>0)combat_sound_at(g,58,0);return 1;}
